import{_ as o,r as s,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"排序记录 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"配置行为","slug":"配置行为","link":"#配置行为","children":[]},{"level":2,"title":"支持的模型类型","slug":"支持的模型类型","link":"#支持的模型类型","children":[{"level":3,"title":"嵌套集","slug":"嵌套集","link":"#嵌套集","children":[]},{"level":3,"title":"简单树","slug":"简单树","link":"#简单树","children":[]},{"level":3,"title":"可排序模型","slug":"可排序模型","link":"#可排序模型","children":[]}]},{"level":2,"title":"对相关记录进行排序","slug":"对相关记录进行排序","link":"#对相关记录进行排序","children":[{"level":3,"title":"可排序的关系模型","slug":"可排序的关系模型","link":"#可排序的关系模型","children":[]}]}],"relativePath":"2.x/zh-cn/backend/reorder.md","filePath":"2.x/zh-cn/backend/reorder.md"}'),i={name:"2.x/zh-cn/backend/reorder.md"};function d(u,a,k,h,g,m){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[n(e),a[0]||(a[0]=c("h1",null,"排序记录",-1)),n(t),a[1]||(a[1]=r(`<p>October CMS 提供了对数据库记录进行排序和重新排序的功能。 对于支持结构化列表的行为，您可以定义一个 <strong>structure</strong> 选项来启用该功能。 各种<a href="./../database/traits.html">模型特征</a> 用于支持重新排序，包括嵌套集、简单树和可排序模型。</p><h2 id="配置行为"><a href="#配置行为" class="header-anchor">#</a> 配置行为</h2><p><a href="./../backend/lists.html">列表行为</a> 后端行为当前支持使用相关定义中的 <strong>structure</strong> 选项重新排序记录的选项。 定义后，页面会显示带有拖动手柄的记录列表，允许对它们进行排序和重组。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  列出行为配置</span>
<span class="token comment"># ===================================</span>

<span class="token comment"># ...</span>

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
</code></pre></div><p>可以使用下面列出的配置选项。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>showTree</strong></td><td>显示父/子记录的树层次结构。 默认值：<code>true</code></td></tr><tr><td><strong>treeExpanded</strong></td><td>默认情况下是否应展开树节点。 默认值：<code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>显示用于重新排序记录的界面。 默认值：<code>true</code></td></tr><tr><td><strong>maxDepth</strong></td><td>定义允许重新排序的最大级别。 默认值：<code>null</code></td></tr><tr><td><strong>dragRow</strong></td><td>allow dragging the entire row in addition to the reorder handle. Default: <code>true</code></td></tr></tbody></table></div><h2 id="支持的模型类型"><a href="#支持的模型类型" class="header-anchor">#</a> 支持的模型类型</h2><p>根据要求，可以使用不同的模型接口来管理嵌套和排序的记录。 行为将根据实现的特征进行调整。</p><h3 id="嵌套集"><a href="#嵌套集" class="header-anchor">#</a> 嵌套集</h3><p>当需要一个固定的结构时，使用 <code>NestedTree</code> Trait。 这包括父子关系以及何时需要以特定顺序显示记录。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>阅读有关 <a href="./../database/traits.html#oc-nested-tree">数据库文档中的 NestedTree Trait</a> 的更多信息。</p><h3 id="简单树"><a href="#简单树" class="header-anchor">#</a> 简单树</h3><p>当需要基本的父子关系时，使用 <code>SimpleTree</code> Trait。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>阅读有关 <a href="./../database/traits.html#oc-simple-tree">数据库文档中的 SimpleTree Trait</a> 的更多信息。</p><h3 id="可排序模型"><a href="#可排序模型" class="header-anchor">#</a> 可排序模型</h3><p>当需要以特定顺序显示记录时，使用 <code>Sortable</code> Trait。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>阅读更多关于<a href="./../database/traits.html#oc-sortable">数据库文档中的可排序Trait</a>。</p><h2 id="对相关记录进行排序"><a href="#对相关记录进行排序" class="header-anchor">#</a> 对相关记录进行排序</h2><p>可以使用 <a href="./../backend/relations.html">Relation Behavior</a> 对相关记录进行排序，下面列出了支持的关系类型。</p><ul><li><a href="./../database/relations.html#relation-one-to-many">一对多</a>在相关模型上使用 <code>Sortable</code> 特征。</li><li><a href="./../database/relations.html#relation-many-to-many">多对多</a>在父模型上使用 <code>SortableRelation</code> 特征(见下文).</li></ul><p><a id="oc-sortable-relation-model"></a></p><h3 id="可排序的关系模型"><a href="#可排序的关系模型" class="header-anchor">#</a> 可排序的关系模型</h3><p>当需要在数据透视表中对记录进行排序时，使用 <code>SortableRelation</code> 特征，例如 <a href="./database/relations.html#many-to-many">多对多</a> 关系类型。 此特征需要在关系中定义 <code>pivotSortable</code> 选项，其中值是在数据透视表中找到的可排序列名称。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SortableRelation</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var array belongsToMany
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name static-context">Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;users_roles&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;pivotSortable&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>然后在您的关系配置中，您应该启用 <code>showReorder</code> 选项并禁用 <code>showTree</code> 选项。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token comment">#...</span>
    <span class="token key atrule">structure</span><span class="token punctuation">:</span>
        <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,29))])}const f=o(i,[["render",d]]);export{y as __pageData,f as default};
